import java.util.*;

public class GradeBook {
    private final TreeMap<String, ArrayList<Integer>> scores = new TreeMap<>();

    private static String tidy(String s) {
        s = s.trim();
        return s.isEmpty() ? s : s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
    }

    public void addScore(String student, int score) {
        if (score < 0 || score > 100) throw new IllegalArgumentException();
        scores.computeIfAbsent(tidy(student), k -> new ArrayList<>()).add(score);
    }

    public double average(String student) {
        List<Integer> s = scores.get(tidy(student));
        if (s == null || s.isEmpty()) return 0.0;
        double sum = 0;
        for (int x : s) sum += x;
        return Math.round(sum / s.size() * 10) / 10.0;
    }

    public String best() {
        String best = "";
        for (String n : scores.keySet()) if (best.isEmpty() || average(n) > average(best)) best = n;
        return best;
    }

    public String report() {
        StringBuilder sb = new StringBuilder();
        for (String n : scores.keySet()) {
            if (sb.length() > 0) sb.append("\n");
            sb.append(n).append(": ").append(average(n));
        }
        return sb.toString();
    }
}
